//! Aperiodic mazes based on Penrose's kite and dart tiling (P2).
//!
//! The tiling is generated by repeated deflation of Robinson triangles
//! (half-kites and half-darts), starting from a "sun" of five kites. The
//! halves are then joined to kites and darts; every tile becomes a cell.
//!
//! Subtype 2 is the Penrose rhombus tiling (P3) of thick (72°) and thin
//! (36°) rhombi, generated with de Bruijn's pentagrid (see multigrid.zig).
//!
//! Half-kite (T, F, S): T is the kite's tip (36°), F the far end of the
//! kite's axis, S a side vertex; T-F is the axis shared with the other half.
//! Half-dart (T, R, S): T is the dart's tip, R the reflex vertex, S a side
//! vertex; T-R is the axis.

const std = @import("std");
const geo = @import("geo.zig");
const mz = @import("maze.zig");
const rng = @import("rng.zig");
const tiling = @import("tiling.zig");
const multigrid = @import("multigrid.zig");

const Allocator = std.mem.Allocator;
const Vec2 = geo.Vec2;
const Maze = mz.Maze;
const Params = mz.Params;

const PHI: f64 = (1.0 + @sqrt(5.0)) / 2.0;

/// Length of the long tile edges in cell units. The average tile then has
/// about the area of a unit square, so `rows` x `columns` gives roughly the
/// same number of cells as an orthogonal maze.
const LONG_EDGE: f64 = std.math.sqrt2;

const TileKind = enum(u8) { kite, dart };

const Tri = struct {
    kind: TileKind,
    /// kite: T, F, S - dart: T, R, S
    a: Vec2,
    b: Vec2,
    c: Vec2,

    fn minX(t: Tri) f64 {
        return @min(t.a.x, t.b.x, t.c.x);
    }
    fn maxX(t: Tri) f64 {
        return @max(t.a.x, t.b.x, t.c.x);
    }
    fn minY(t: Tri) f64 {
        return @min(t.a.y, t.b.y, t.c.y);
    }
    fn maxY(t: Tri) f64 {
        return @max(t.a.y, t.b.y, t.c.y);
    }
};

/// Point on the line from `p` to `q` at 1/φ of the distance.
inline fn golden(p: Vec2, q: Vec2) Vec2 {
    return p.add(q.sub(p).scale(1.0 / PHI));
}

/// One deflation step: every half-tile is replaced by smaller half-tiles
/// (scale 1/φ).
fn deflate(gpa: Allocator, in: []const Tri, out: *std.ArrayListUnmanaged(Tri)) !void {
    out.clearRetainingCapacity();
    for (in) |t| switch (t.kind) {
        .kite => {
            // half-kite (T, F, S) -> half-kites (S, D, F), (S, D, G), half-dart (T, G, D)
            const T = t.a;
            const F = t.b;
            const S = t.c;
            const D = golden(T, F);
            const G = golden(S, T);
            try out.appendSlice(gpa, &.{
                .{ .kind = .kite, .a = S, .b = D, .c = F },
                .{ .kind = .kite, .a = S, .b = D, .c = G },
                .{ .kind = .dart, .a = T, .b = G, .c = D },
            });
        },
        .dart => {
            // half-dart (T, R, S) -> half-kite (T, R, G), half-dart (S, G, R)
            const T = t.a;
            const R = t.b;
            const S = t.c;
            const G = golden(T, S);
            try out.appendSlice(gpa, &.{
                .{ .kind = .kite, .a = T, .b = R, .c = G },
                .{ .kind = .dart, .a = S, .b = G, .c = R },
            });
        },
    };
}

pub fn newPenroseMaze(gpa: Allocator, params: *Params, rand: *rng.Random) !*Maze {
    var arena_state = std.heap.ArenaAllocator.init(gpa);
    defer arena_state.deinit();
    const tmp = arena_state.allocator();

    const w: f64 = @floatFromInt(params.columns);
    const h: f64 = @floatFromInt(params.rows);
    const half_diag = @sqrt(w * w + h * h) / 2.0;

    // a randomly rotated and shifted sun, big enough to cover the maze
    const angle = rand.unit() * 2.0 * std.math.pi;
    const off_r = @sqrt(rand.unit()) * half_diag;
    const off_a = rand.unit() * 2.0 * std.math.pi;
    const off = geo.sincos(off_a);
    const center = Vec2{ .x = w / 2.0 + off.cos * off_r, .y = h / 2.0 + off.sin * off_r };
    // the sun's border is at least cos(18°) times its radius away
    const needed = (half_diag + off_r + 2.0 * LONG_EDGE) / @cos(std.math.pi / 10.0);
    var radius = LONG_EDGE;
    var steps: usize = 0;
    while (radius < needed) : (steps += 1) radius *= PHI;

    var tris: std.ArrayListUnmanaged(Tri) = .empty;
    var next: std.ArrayListUnmanaged(Tri) = .empty;
    for (0..5) |i| {
        const fa = angle + @as(f64, @floatFromInt(i)) * 2.0 * std.math.pi / 5.0;
        const F = center.add((Vec2{ .x = radius }).rot(fa));
        const S1 = center.add((Vec2{ .x = radius }).rot(fa - std.math.pi / 5.0));
        const S2 = center.add((Vec2{ .x = radius }).rot(fa + std.math.pi / 5.0));
        try tris.appendSlice(tmp, &.{
            .{ .kind = .kite, .a = center, .b = F, .c = S1 },
            .{ .kind = .kite, .a = center, .b = F, .c = S2 },
        });
    }

    // deflate, dropping triangles far away from the maze area (children lie
    // within their parent, so this never removes needed tiles)
    const margin = 2.0 * LONG_EDGE;
    for (0..steps) |_| {
        try deflate(tmp, tris.items, &next);
        std.mem.swap(std.ArrayListUnmanaged(Tri), &tris, &next);
        var k: usize = 0;
        for (tris.items) |t| {
            if (t.maxX() < -margin or t.minX() > w + margin or t.maxY() < -margin or t.minY() > h + margin) continue;
            tris.items[k] = t;
            k += 1;
        }
        tris.items.len = k;
    }

    // join halves to tiles
    var verts: tiling.PointSet = .{};
    var halves: std.AutoHashMapUnmanaged([3]u32, u32) = .empty;
    var tiles: std.ArrayListUnmanaged(tiling.Tile) = .empty;
    for (tris.items, 0..) |t, ti| {
        const ia = try verts.id(tmp, t.a);
        const ib = try verts.id(tmp, t.b);
        const ic = try verts.id(tmp, t.c);
        const key = [3]u32{ @backingInt(t.kind), ia, ib };
        const gop = try halves.getOrPut(tmp, key);
        if (!gop.found_existing) {
            gop.value_ptr.* = @intCast(ti);
            continue;
        }
        const o = tris.items[gop.value_ptr.*];
        const ic2 = try verts.id(tmp, o.c);
        // the tile's center: mean of the centroids of both halves (on the axis)
        const c1 = t.a.add(t.b).add(t.c).scale(1.0 / 3.0);
        const c2 = o.a.add(o.b).add(o.c).scale(1.0 / 3.0);
        const ctr = c1.mean(c2);
        if (ctr.x < 0 or ctr.x > w or ctr.y < 0 or ctr.y > h) continue;
        const v = try tmp.dupe(u32, &.{ ia, ic, ib, ic2 });
        // make the vertex order counter clockwise
        const p = [4]Vec2{ t.a, t.c, t.b, o.c };
        var area: f64 = 0;
        for (0..4) |i| area += p[i].x * p[(i + 1) % 4].y - p[(i + 1) % 4].x * p[i].y;
        if (area < 0) std.mem.reverse(u32, v);
        try tiles.append(tmp, .{
            .type = if (t.kind == .kite) mz.TYPE_A else mz.TYPE_A + 1,
            .verts = v,
            .center = ctr,
        });
    }
    return tiling.buildMaze(gpa, params, rand, verts.points.items, tiles.items);
}

/// Edge length of the rhombi: there are φ thick rhombi (area sin 72°) per
/// thin one (area sin 36°), this makes the mean tile area 1.
const RHOMB_EDGE: f64 = 1.0 / @sqrt((PHI * @sin(2.0 * std.math.pi / 5.0) + @sin(std.math.pi / 5.0)) / (PHI + 1.0));

/// Pentagrid directions j and k enclose 72°·(k − j): thick rhombi for
/// k − j = 1, 4 (72°, 288°), thin ones for 2, 3 (144°, 216°).
fn rhombType(j: usize, k: usize) u8 {
    return if (k - j == 1 or k - j == 4) mz.TYPE_A else mz.TYPE_A + 1;
}

pub fn newPenroseRhombMaze(gpa: Allocator, params: *Params, rand: *rng.Random) !*Maze {
    var g: multigrid.Grid = .{ .n = 5, .step = 2.0 * std.math.pi / 5.0, .gamma = undefined, .edge = RHOMB_EDGE, .tileType = rhombType };
    // the offsets must add up to an integer for a Penrose tiling
    var sum: f64 = 0;
    for (g.gamma[0..4]) |*x| {
        x.* = rand.unit();
        sum += x.*;
    }
    g.gamma[4] = @ceil(sum) - sum;
    return multigrid.newMultigridMaze(gpa, params, rand, g);
}

test "penrose rhombs have equal edges and a thick/thin ratio near phi" {
    const gpa = std.testing.allocator;
    var params: Params = .{ .rows = 30, .columns = 30 };
    var rand = rng.Random.init(4);
    const m = try newPenroseRhombMaze(gpa, &params, &rand);
    defer m.deinit();
    var thick: f64 = 0;
    var thin: f64 = 0;
    var area: f64 = 0;
    for (m.cells[0..m.n_cells]) |*c| {
        try std.testing.expectEqual(@as(usize, 4), c.nWalls());
        for (0..4) |i| try std.testing.expectApproxEqAbs(RHOMB_EDGE, m.cellWall(c, i).length(), 1e-9);
        if (c.type == mz.TYPE_A) thick += 1 else thin += 1;
    }
    area = thick * @sin(2.0 * std.math.pi / 5.0) + thin * @sin(std.math.pi / 5.0);
    try std.testing.expect(@abs(thick / thin - PHI) < 0.1);
    // about one unit of area per cell
    try std.testing.expectApproxEqAbs(@as(f64, 1), area * RHOMB_EDGE * RHOMB_EDGE / (thick + thin), 0.03);
    try std.testing.expect(m.n_cells > 800 and m.n_cells < 1000);
}

test "deflation keeps the kite/dart ratio near phi" {
    const gpa = std.testing.allocator;
    var params: Params = .{ .rows = 30, .columns = 30 };
    var rand = rng.Random.init(3);
    const m = try newPenroseMaze(gpa, &params, &rand);
    defer m.deinit();
    var kites: f64 = 0;
    var darts: f64 = 0;
    for (m.cells[0..m.n_cells]) |*c| {
        try std.testing.expectEqual(@as(usize, 4), c.nWalls());
        if (c.type == mz.TYPE_A) kites += 1 else darts += 1;
        // two long and two short edges
        var long: usize = 0;
        for (0..4) |i| {
            const l = m.cellWall(c, i).length();
            if (@abs(l - LONG_EDGE) < 1e-6) {
                long += 1;
            } else {
                try std.testing.expectApproxEqAbs(LONG_EDGE / PHI, l, 1e-6);
            }
        }
        try std.testing.expectEqual(@as(usize, 2), long);
    }
    try std.testing.expect(@abs(kites / darts - PHI) < 0.1);
    try std.testing.expect(m.n_cells > 600 and m.n_cells < 1200);
}
